(function(){window.PhysicaRankPyqNeet_physics_semiconductorelectronics=[{id:"neet-2026-q003",pn:3,y:"NEET 2026 \xB7 21 Jun \xB7 Re-exam",tp:"Semiconductor Electronics",st:"p-n junction biasing, depletion width",q:"Three identical p-n junction diodes D\u2081, D\u2082, and D\u2083 are connected across a battery as shown in the figure. If the width of the depletion regions of D\u2081, D\u2082 and D\u2083 are W\u2081, W\u2082 and W\u2083, respectively, then the correct option is:",o:["W\u2083 = W\u2081 > W\u2082","W\u2083 > W\u2082 > W\u2081","W\u2082 > W\u2081 = W\u2083","W\u2081 > W\u2082 > W\u2083"],c:1,s:`D\u2081 is forward biased.
Depletion region of a forward-biased diode (W\u2081) is the minimum.
D\u2083 is reverse biased.
Depletion region of a reverse-biased diode (W\u2083) is the maximum.
D\u2082 is unbiased.
Its depletion region (W\u2082) lies between W\u2081 and W\u2083.
So W\u2083 > W\u2082 > W\u2081.`,fig:{w:250,h:225,alt:"Three branches across a 5 V battery: 1 k\u03A9 with D1 (forward), 1 k\u03A9 with D2 (middle branch not joined to the right wire), and D3 (reversed) with 1 k\u03A9.",d:[["l",47,33,80,33,""],["p","M80 33 L82.7 28 L85.4 38 L88.1 28 L90.8 38 L93.5 28 L96.2 38 L98.8 28 L101.5 38 L104.2 28 L106.9 38 L109.6 28 L112.3 38 L115 33"],["l",115,33,152,33,""],["p","M152 25L152 41L170 33Z","F"],["l",170,25,170,41,""],["l",170,33,204,33,""],["t",77,18,"1 k\u03A9",""],["t",150,16,"D\u2081",""],["l",20,95,80,95,""],["p","M80 95 L82.7 90 L85.4 100 L88.1 90 L90.8 100 L93.5 90 L96.2 100 L98.8 90 L101.5 100 L104.2 90 L106.9 100 L109.6 90 L112.3 100 L115 95"],["l",115,95,152,95,""],["p","M152 87L152 103L170 95Z","F"],["l",170,87,170,103,""],["l",170,95,178,95,""],["c",180,95,1.5,"F"],["c",194,95,1.5,"F"],["l",204,95,232,95,""],["t",77,80,"1 k\u03A9",""],["t",150,78,"D\u2082",""],["l",47,150,82,150,""],["p","M100 142L100 158L82 150Z","F"],["l",82,142,82,158,""],["l",100,150,140,150,""],["p","M140 150 L142.7 145 L145.4 155 L148.1 145 L150.8 155 L153.5 145 L156.2 155 L158.8 145 L161.5 155 L164.2 145 L166.9 155 L169.6 145 L172.3 155 L175 150"],["l",175,150,204,150,""],["t",86,135,"D\u2083",""],["t",140,135,"1 k\u03A9",""],["l",47,33,47,150,""],["l",204,33,204,150,""],["l",20,95,20,193,""],["l",232,95,232,193,""],["l",20,193,122,193,""],["l",128,193,232,193,""],["l",122,184,122,202,""],["l",128,189,128,197,"B"],["t",128,218,"5 V","m"]]}},{id:"neet-2026-q029",pn:29,y:"NEET 2026 \xB7 21 Jun \xB7 Re-exam",tp:"Semiconductor Electronics",st:"Zener diode in reverse bias",q:"An ideal Zener diode with breakdown voltage of \u22123 V is reverse biased with a negative input voltage V\u1D62 = \u22125 V. The magnitude of voltage difference between point B and A is:",o:["2 V","1 V","0 V","3 V"],c:0,s:`The input voltage magnitude (5 V) is greater than the Zener voltage magnitude (3 V), so the Zener diode is in breakdown.
The voltage across the Zener is V_zener = 3 V.
Total voltage V_total = 5 V.
The rest of the voltage falls across the resistor between B and A.
|V_BA| = 5 \u2212 3 = 2 V.`,fig:{w:200,h:130,alt:"Rectangular circuit: top wire has point C, a Zener diode, point B, resistor R and point A in order; the bottom wire holds a battery.",d:[["p","M20 40 V110 H92"],["p","M108 110 H180 V40 H170"],["l",92,100,92,120],["l",98,104,98,116,"B"],["l",98,110,108,110],["l",20,40,45,40],["l",45,40,60,40],["p","M60 33 L60 47 M60 33 L57 31 M60 47 L63 49"],["p","M60 40 L74 33 L74 47 Z"],["l",74,40,100,40],["p","M100 40 H108 L111 35 L116 45 L121 35 L126 45 L131 35 L134 40 H170"],["t",45,26,"C","m"],["c",45,40,2.5,"F"],["c",100,40,2.5,"F"],["t",100,26,"B","m"],["t",122,26,"R","m"],["c",165,40,2.5,"F"],["t",165,26,"A","m"],["l",165,40,180,40]]},sfig:{w:200,h:130,alt:"Same circuit: top wire C, Zener diode, B, resistor R, A; battery on the bottom wire.",d:[["p","M20 40 V110 H92"],["p","M108 110 H180 V40 H170"],["l",92,100,92,120],["l",98,104,98,116,"B"],["l",98,110,108,110],["l",20,40,45,40],["l",45,40,60,40],["p","M60 33 L60 47 M60 33 L57 31 M60 47 L63 49"],["p","M60 40 L74 33 L74 47 Z"],["l",74,40,100,40],["p","M100 40 H108 L111 35 L116 45 L121 35 L126 45 L131 35 L134 40 H170"],["t",45,26,"C","m"],["c",45,40,2.5,"F"],["c",100,40,2.5,"F"],["t",100,26,"B","m"],["t",122,26,"R","m"],["c",165,40,2.5,"F"],["t",165,26,"A","m"],["l",165,40,180,40]]}},{id:"neet-2025-q008",pn:8,y:"NEET 2025",tp:"Semiconductor Electronics",st:"Logic gates",q:"The output (Y) of the given logic implementation is similar to the output of an/a _____ gate.",o:["AND","NAND","OR","NOR"],c:3,s:`Let Y\u2081 be the output of the NOR gate (inputs A and B) and Y\u2082 the output of the NAND gate (inputs B and A).
Y\u2081 = (A + B)\u2032 (overbar on A + B)
Y\u2082 = (A\xB7B)\u2032 (overbar on A\xB7B)
Y = Y\u2081\xB7Y\u2082
= (A + B)\u2032 \xB7 (A\xB7B)\u2032
= (A + B + A\xB7B)\u2032
= (A + B(1 + A))\u2032
= (A + B)\u2032, which is a NOR gate.`,fig:{w:350,h:185,alt:"Inputs A and B feed a NOR gate (A, B) and a NAND gate (B, A); their outputs feed an AND gate with output Y.",d:[["c",31.5,29.7,3.6,""],["l",35.1,29.7,79.2,29.7,""],["c",31.5,82.8,3.6,""],["l",35.1,82.8,52.2,82.8,""],["l",52.2,54.9,52.2,109.8,""],["c",31.5,135,3.6,""],["l",35.1,135,91.8,135,""],["l",52.2,54.9,77.4,54.9,""],["l",52.2,109.8,86.4,109.8,""],["p","M72 14.4 C94.5 14.4 112.5 31.5 114.3 41.4 C112.5 54 94.5 68.4 72 68.4 C85.5 49.5 85.5 33.3 72 14.4 Z",""],["c",117.9,41.4,3.6,""],["l",121.5,41.4,163.8,41.4,""],["l",163.8,41.4,163.8,70.2,""],["l",163.8,70.2,196.2,70.2,""],["p","M84.6 97.2 H104.4 A27 27 0 0 1 104.4 151.2 H84.6 Z",""],["c",130.5,124.2,3.6,""],["l",134.1,124.2,163.8,124.2,""],["l",163.8,124.2,163.8,99,""],["l",163.8,99,196.2,99,""],["p","M196.2 57.6 H216 A27 27 0 0 1 216 111.6 H196.2 Z",""],["l",238.5,84.6,285.3,84.6,""],["c",289.8,84.6,3.6,""],["t",10.8,35.1,"A",""],["t",9,87.3,"B",""],["t",10.8,139.5,"A",""],["t",300.6,86.4,"Y",""]]},sfig:{w:350,h:185,alt:"Same circuit: NOR output Y1 and NAND output Y2 feed the final AND gate giving Y; inputs A (top), B (middle), A (bottom).",d:[["c",29.7,26.1,3.6,""],["l",33.3,26.1,79.2,26.1,""],["c",29.7,79.2,3.6,""],["l",33.3,79.2,49.5,79.2,""],["l",49.5,51.3,49.5,108,""],["c",29.7,131.4,3.6,""],["l",33.3,131.4,90.9,131.4,""],["l",49.5,51.3,77.4,51.3,""],["l",49.5,108,85.5,108,""],["p","M72 10.8 C94.5 10.8 112.5 27.9 114.3 37.8 C112.5 50.4 94.5 64.8 72 64.8 C85.5 45.9 85.5 29.7 72 10.8 Z",""],["c",117.9,37.8,3.6,""],["l",121.5,37.8,162.9,37.8,""],["l",162.9,37.8,162.9,66.6,""],["l",162.9,66.6,195.3,66.6,""],["p","M83.7 93.6 H103.5 A27 27 0 0 1 103.5 147.6 H83.7 Z",""],["c",129.6,120.6,3.6,""],["l",133.2,120.6,162.9,120.6,""],["l",162.9,120.6,162.9,95.4,""],["l",162.9,95.4,195.3,95.4,""],["p","M195.3 54 H215.1 A27 27 0 0 1 215.1 108 H195.3 Z",""],["l",237.6,81,283.5,81,""],["c",288,81,3.6,""],["t",9.9,29.7,"A",""],["t",8.1,83.7,"B",""],["t",9.9,135.9,"A",""],["t",297.9,83.7,"Y",""],["t",137.7,27,"Y\u2081",""],["t",144,135,"Y\u2082",""]]}},{id:"neet-2025-q040",pn:40,y:"NEET 2025",tp:"Semiconductor Electronics",st:"Full wave rectifier",q:"A full wave rectifier circuit with diodes (D\u2081) and (D\u2082) is shown in the figure. If input supply voltage V_in = 220sin(100\u03C0t) volt, then at t = 15 msec",o:["D\u2081 is forward biased, D\u2082 is reverse biased","D\u2081 is reverse biased, D\u2082 is forward biased.","D\u2081 and D\u2082 both are forward biased","D\u2081 and D\u2082 both are reverse biased"],c:1,s:`V_in = 220sin(100\u03C0t) volt, t = 15 ms = 0.015 s.
\u03C9 = 100\u03C0, so 2\u03C0/T = 100\u03C0.
T = 1/50 s = 0.02 s.
So t = 3T/4, i.e. the negative half cycle.
The negative half cycle makes D\u2081 reverse biased and D\u2082 forward biased.`,fig:{w:370,h:215,alt:"Full-wave rectifier: AC source and primary coil, transformer with centre-tapped secondary, diodes D1 and D2 joined to load RL and two output terminals",d:[["l",37,42,93,42],["l",37,42,37,94],["l",37,120,37,170],["l",37,170,93,170],["l",93,42,93,85],["p","M93 85 A5.9 5.9 0 0 0 93 96.8 A5.9 5.9 0 0 0 93 108.6 A5.9 5.9 0 0 0 93 120.4 A5.9 5.9 0 0 0 93 132.2"],["l",93,132,93,170],["c",37,107,13],["t",37,111,"~","m"],["t",5,111,"V"],["t",15,117,"in","s"],["l",110,78,110,122],["l",120,78,120,122],["p","M138 85 A5.9 5.9 0 0 0 138 96.8 A5.9 5.9 0 0 0 138 108.6 A5.9 5.9 0 0 0 138 120.4 A5.9 5.9 0 0 0 138 132.2"],["l",138,85,138,42],["l",138,42,232,42],["l",138,132,138,170],["l",138,170,232,170],["p","M232 34 L232 50 L248 42 Z"],["l",250,34,250,50],["l",250,42,281,42],["p","M232 162 L232 178 L248 170 Z"],["l",250,162,250,178],["l",250,170,281,170],["l",281,42,281,170],["l",281,122,356,122],["c",360,122,4],["l",312,122,312,138],["p","M312 138 L307 141.7 L317 149 L307 156.3 L317 163.7 L307 171 L317 178.3 L312 182"],["l",312,182,312,205],["l",177,205,356,205],["c",360,205,4],["l",177,158,177,117],["l",177,117,162,117,"a"],["p","M177 158 A12 12 0 0 0 177 182"],["l",177,182,177,205],["t",249,28,"D"],["t",259,32,"1","s"],["t",245,150,"D"],["t",255,154,"2","s"],["t",325,168,"R"],["t",334,172,"L","s"]]}}]})();
